import java.math.BigDecimal;

/**
 * FeeCalculator 的独立测试类，使用 main 方法加断言，不依赖任何测试框架。
 *
 * 覆盖：负数、null、0、100、200 及阈值上下相邻金额；配送费额外覆盖件数 0 与 1；
 * 同时验证返回值精度（2 位小数）与输入 BigDecimal 不被修改。
 */
public final class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ===== 配送费：正常与边界 =====
        // 件数为 0，无论金额如何都返回 0
        assertDeliveryFee("delivery itemCount=0 amount=0", "0.00", new BigDecimal("0"), 0);
        assertDeliveryFee("delivery itemCount=0 amount=200", "0.00", new BigDecimal("200"), 0);
        assertDeliveryFee("delivery itemCount=0 amount=500", "0.00", new BigDecimal("500"), 0);

        // 件数 > 0，金额严格大于 200 免配送费
        assertDeliveryFee("delivery itemCount=1 amount=200.01", "0.00", new BigDecimal("200.01"), 1);
        assertDeliveryFee("delivery itemCount=1 amount=201", "0.00", new BigDecimal("201"), 1);
        assertDeliveryFee("delivery itemCount=5 amount=1000", "0.00", new BigDecimal("1000"), 5);

        // 金额恰好 200 不免配送，返回 12
        assertDeliveryFee("delivery itemCount=1 amount=200", "12.00", new BigDecimal("200"), 1);

        // 金额小于 200，返回 12
        assertDeliveryFee("delivery itemCount=1 amount=199.99", "12.00", new BigDecimal("199.99"), 1);
        assertDeliveryFee("delivery itemCount=1 amount=100", "12.00", new BigDecimal("100"), 1);
        assertDeliveryFee("delivery itemCount=1 amount=0", "12.00", new BigDecimal("0"), 1);
        assertDeliveryFee("delivery itemCount=1 amount=0.01", "12.00", new BigDecimal("0.01"), 1);

        // ===== 配送费：非法输入 =====
        assertThrows("delivery amount=null", () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("delivery amount=-0.01", () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("delivery amount=-100", () -> FeeCalculator.deliveryFee(new BigDecimal("-100"), 1));
        assertThrows("delivery itemCount=-1", () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));

        // ===== 服务费：正常与边界 =====
        assertServiceFee("service amount=0", "0.00", new BigDecimal("0"));
        assertServiceFee("service amount=0.01", "2.00", new BigDecimal("0.01"));
        assertServiceFee("service amount=100", "2.00", new BigDecimal("100"));
        assertServiceFee("service amount=99.99", "2.00", new BigDecimal("99.99"));
        assertServiceFee("service amount=100.01", "5.00", new BigDecimal("100.01"));
        assertServiceFee("service amount=101", "5.00", new BigDecimal("101"));
        assertServiceFee("service amount=1000", "5.00", new BigDecimal("1000"));

        // 服务费不使用配送费的 200 阈值：金额 200 仍按 >100 规则返回 5
        assertServiceFee("service amount=200", "5.00", new BigDecimal("200"));

        // ===== 服务费：非法输入 =====
        assertThrows("service amount=null", () -> FeeCalculator.serviceFee(null));
        assertThrows("service amount=-0.01", () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));
        assertThrows("service amount=-100", () -> FeeCalculator.serviceFee(new BigDecimal("-100")));

        // ===== 输入 BigDecimal 不被修改 =====
        assertInputUnchanged();

        // ===== 汇总 =====
        System.out.println("通过：" + passed + "，失败：" + failed);
        if (failed > 0) {
            throw new AssertionError("存在失败用例：" + failed);
        }
        System.out.println("全部测试通过。");
    }

    // ---------- 断言辅助方法 ----------

    private static void assertDeliveryFee(String name, String expected, BigDecimal amount, int itemCount) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(amount, itemCount);
            checkEquals(name, expected, actual);
        } catch (Exception e) {
            fail(name, "抛出异常：" + e);
        }
    }

    private static void assertServiceFee(String name, String expected, BigDecimal amount) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(amount);
            checkEquals(name, expected, actual);
        } catch (Exception e) {
            fail(name, "抛出异常：" + e);
        }
    }

    private static void checkEquals(String name, String expected, BigDecimal actual) {
        if (actual == null) {
            fail(name, "返回值为 null");
            return;
        }
        // 校验数值相等
        if (actual.compareTo(new BigDecimal(expected)) != 0) {
            fail(name, "期望 " + expected + "，实际 " + actual);
            return;
        }
        // 校验精度为 2 位小数
        if (actual.scale() != 2) {
            fail(name, "期望小数位 2，实际 " + actual.scale() + "（值 " + actual + "）");
            return;
        }
        pass(name);
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            fail(name, "期望抛出 IllegalArgumentException，但未抛出");
        } catch (IllegalArgumentException e) {
            pass(name);
        } catch (Exception e) {
            fail(name, "期望 IllegalArgumentException，实际抛出 " + e.getClass().getName());
        }
    }

    private static void assertInputUnchanged() {
        BigDecimal amount = new BigDecimal("200.00");
        BigDecimal before = new BigDecimal(amount.toPlainString());
        FeeCalculator.deliveryFee(amount, 1);
        FeeCalculator.serviceFee(amount);
        if (amount.compareTo(before) == 0 && amount.scale() == before.scale()) {
            pass("输入 BigDecimal 未被修改");
        } else {
            fail("输入 BigDecimal 未被修改", "修改前 " + before + "，修改后 " + amount);
        }
    }

    private static void pass(String name) {
        passed++;
        System.out.println("[PASS] " + name);
    }

    private static void fail(String name, String message) {
        failed++;
        System.out.println("[FAIL] " + name + " -> " + message);
    }
}
