                FeeCalculator.serviceFee(new BigDecimal("0")));

        // 0 < amount <= 100：返回 2
        assertFee("service amount=0.01", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("0.01")));
        assertFee("service amount=100", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("100")));
        assertFee("service amount=99.99", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("99.99")));

