            throw new AssertionError("input BigDecimal was modified");
        }
    }

    private static void assertFee(String name, String expected, BigDecimal actual) {
        BigDecimal expectedValue = new BigDecimal(expected);
        if (actual == null) {
            throw new AssertionError(name + " expected " + expected + " but was null");
        }
        if (actual.compareTo(expectedValue) != 0) {
            throw new AssertionError(name + " expected " + expected + " but was " + actual);
        }
        if (actual.scale() != 2) {
            throw new AssertionError(name + " expected scale 2 but was " + actual.scale());
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException ex) {
            return;
        }
        throw new AssertionError(name + " expected IllegalArgumentException");
    }
